  /// <summary>
  /// How a softphone account secures its SIP signalling to the project&amp;apos;s Asterisk. Both modes use TLS
  /// for signalling, SRTP for media and SIP digest authentication with the account&amp;apos;s own credentials;
  /// they differ in which TLS port the softphone connects to and whether it must present a client
  /// certificate.
  /// </summary>
  public enum SoftphoneTransportSecurity {
    /// <summary>
    /// Unspecified: identical to &lt;code>SOFTPHONE_TRANSPORT_SECURITY_CLIENT_CERTIFICATE&lt;/code> on create.
    /// The zero value is the stronger mode, so a caller that says nothing gets mutual TLS. Never returned
    /// on a stored account.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_TRANSPORT_SECURITY_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Mutual TLS. The softphone connects to the project&amp;apos;s internal TLS port, which requires a client
    /// certificate, and presents the certificate VTSI issued for this account from the project&amp;apos;s
    /// SOFTPHONE certificate authority. SIP digest authentication is required in addition.
    /// The Asterisk cannot bind an account to one port: the account&amp;apos;s PASSWORD alone can still
    /// REGISTER over the external TLS port and so receive the account&amp;apos;s incoming calls, while every
    /// call it places that did not arrive over TLS on the internal port is refused with 403. Treat the
    /// password as a full credential of the account.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_TRANSPORT_SECURITY_CLIENT_CERTIFICATE")] ClientCertificate = 1,
    /// <summary>
    /// Server-authenticated TLS only. The softphone connects to the project&amp;apos;s external TLS port, which
    /// does not ask for a client certificate, and authenticates with SIP digest alone. Intended for
    /// softphone editions without client-certificate support, e.g. some Zoiper editions. A call it places
    /// over a cleartext transport is refused with 403.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_TRANSPORT_SECURITY_SERVER_TLS_ONLY")] ServerTlsOnly = 2,
  }

  /// <summary>
  /// Lifecycle status of a softphone client certificate.
  /// </summary>
  public enum SoftphoneCertificateStatus {
    /// <summary>
    /// Unspecified. Never returned; in a filter it matches nothing and is rejected with
    /// &lt;code>INVALID_ARGUMENT&lt;/code>.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_CERTIFICATE_STATUS_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The account&amp;apos;s current certificate. It is accepted by the project&amp;apos;s Asterisk until it
    /// expires, or until the project&amp;apos;s Asterisk port changes: the certificate authorities belong to
    /// the port, so a port change voids every issued certificate (the stored status is not changed; rotate
    /// the certificate). An account holds at most one ACTIVE certificate.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_CERTIFICATE_STATUS_ACTIVE")] Active = 1,
    /// <summary>
    /// Replaced by a newer certificate through &lt;code>RotateSoftphoneCredentials&lt;/code>, which rotated the
    /// account&amp;apos;s password with it. Still completes a TLS handshake until it expires, but no longer
    /// gets its holder the account.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_CERTIFICATE_STATUS_SUPERSEDED")] Superseded = 2,
    /// <summary>
    /// Explicitly revoked through &lt;code>RevokeSoftphoneCertificate&lt;/code>, or because its account was
    /// deleted. Still completes a TLS handshake until it expires (the Asterisk has no revocation list),
    /// but no longer gets its holder the account.
    /// </summary>
    [pbr::OriginalName("SOFTPHONE_CERTIFICATE_STATUS_REVOKED")] Revoked = 3,
  }

